import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation using a bit array and custom hash functions.

    Attributes:
        size (int): The size of the bit array.
        hash_count (int): The number of hash functions.
        bit_array (list): The underlying bit array represented as a list of bools.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_number_of_hash_functions(expected_items, self.size)
        self.bit_array = [False] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((n * math.log(p)) / math.log(1 / (math.pow(2, math.log(2)))))

    def _optimal_number_of_hash_functions(self, n: int, m: int) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((m / n) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Create a hash for the item using a specified seed."""
        hash_value = hashlib.md5((str(seed) + item).encode()).hexdigest()
        return int(hash_value, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if not self.bit_array[index]:
                return False
        return True

